import{_ as o,a8 as t,o as s,c as r,ah as i,aF as c,K as n}from"./chunks/framework.B8M9fnPY.js";import"./chunks/theme.CsDPudC3.js";const f=JSON.parse('{"title":"Function Call 概述","description":"","frontmatter":{"title":"Function Call 概述","abstract":"Function Call 函数调用机制概述，讲解大模型识别用户意图、输出结构化函数参数、由程序执行并回传结果的工作流程与应用场景。","created":"2026-07-09T00:00:00.000Z","tags":["AI","Function Call"],"type":"概念解释","related":["[[AI 应用核心范式-MOC]]","[[Function Call 实战]]"],"reference":"","category":["🧩 AI框架与Agent","AI 应用核心范式"]},"headers":[],"relativePath":"vault/Knowledge/AI/Function Call 概述.md","filePath":"vault/Knowledge/AI/Function Call 概述.md","lastUpdated":1790655645000}'),d={name:"vault/Knowledge/AI/Function Call 概述.md"};function h(p,a,b,u,g,_){const e=t("NolebaseGitContributors"),l=t("NolebaseGitChangelog");return s(),r("div",null,[a[0]||(a[0]=i('<h1 id="function-call-概述" tabindex="-1">Function Call 概述 <a class="header-anchor" href="#function-call-概述" aria-label="Permalink to “Function Call 概述”">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to “定义”">​</a></h2><p>2023年6月 OpenAI 发布 Function Call（函数调用）功能：在语言模型中集成外部函数或 API 的调用能力，模型可在生成文本的过程中调用外部函数或服务，获取额外数据或执行特定任务。</p><blockquote><p><strong>关键约束</strong>：大模型不会真正执行函数，仅返回函数名称和参数 JSON。开发者需在应用层解析参数后自行调用函数，再将结果返回给模型生成最终回复。</p></blockquote><p><img src="'+c+`"></p><h2 id="能解决的问题" tabindex="-1">能解决的问题 <a class="header-anchor" href="#能解决的问题" aria-label="Permalink to “能解决的问题”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>说明</th></tr></thead><tbody><tr><td><strong>信息实时性</strong></td><td>训练数据截止时间限制，无法获取最新信息（新闻、股价等）。通过 Function Call 可实时调取外部数据</td></tr><tr><td><strong>数据局限性</strong></td><td>训练数据无法覆盖所有专业领域（医学、法律等）。Function Call 允许调用外部数据库或专业 API</td></tr><tr><td><strong>功能扩展性</strong></td><td>大模型无法内置所有功能。通过 Function Call 可扩展计算、分析等外部能力</td></tr></tbody></table><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to “工作原理”">​</a></h2><h3 id="无函数调用时" tabindex="-1">无函数调用时 <a class="header-anchor" href="#无函数调用时" aria-label="Permalink to “无函数调用时”">​</a></h3><p>用户 → Chat Server → GPT 模型 → 返回文本 → 用户（简单一问一答循环）</p><h3 id="有函数调用时" tabindex="-1">有函数调用时 <a class="header-anchor" href="#有函数调用时" aria-label="Permalink to “有函数调用时”">​</a></h3><ol><li>用户发请求（含 prompt + functions 定义）给 Chat Server</li><li>GPT 根据 prompt 判断：直接文本回复 or 返回函数调用 JSON</li><li>若为函数调用格式，Chat Server <strong>执行该函数</strong>，将结果返回给 GPT</li><li>GPT 综合函数结果，生成自然语言回复</li></ol><h2 id="调用流程" tabindex="-1">调用流程 <a class="header-anchor" href="#调用流程" aria-label="Permalink to “调用流程”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>用户提问</span></span>
<span class="line"><span>  → 模型判断是否需调用工具</span></span>
<span class="line"><span>    → 是：返回 {function_name, arguments}</span></span>
<span class="line"><span>      → 后端解析参数，执行函数</span></span>
<span class="line"><span>      → 函数结果注入对话上下文</span></span>
<span class="line"><span>      → 模型基于结果生成最终回复</span></span>
<span class="line"><span>    → 否：直接生成回复</span></span></code></pre></div><h2 id="核心要素" tabindex="-1">核心要素 <a class="header-anchor" href="#核心要素" aria-label="Permalink to “核心要素”">​</a></h2><ul><li><strong>tools 定义</strong>：JSON Schema 格式描述函数名、用途、参数类型和必填项</li><li><strong>tool_choice</strong>：<code>auto</code> 让模型自行决定是否调用；可强制 <code>none</code> 或指定函数</li><li><strong>多轮对话</strong>：函数调用结果需以 <code>role: tool</code> 消息追加到对话历史 <em>（内容由AI生成，仅供参考）</em></li></ul>`,16)),n(e),n(l)])}const k=o(d,[["render",h]]);export{f as __pageData,k as default};
